import unittest

from tmc import points
from tmc.utils import load_module, reload_module, get_stdout

exercise = 'src.emoticon'
@points('1.emoticon')
class EmoticonTest(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.module = load_module(exercise, 'en')

    def test_print_emoticon(self):
        reload_module(self.module)
        output = get_stdout()
        self.assertTrue(output.startswith(":"), "Make sure that you don't print out extra characters before the emoticon starts.")
        self.assertTrue(output.endswith(")"), "Make sure that you don't print out extra characters after the emoticon ends.")
        self.assertEqual(output, ":-)", "Emoticon is malformed.")

if __name__ == '__main__':
    unittest.main()

import unittest

from tmc import points
from tmc.utils import load_module, reload_module, get_stdout

exercise = 'src.seven_brothers'
@points('1.seven_brothers')
class SevenBrothersTest(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.module = load_module(exercise, 'en')

    def test_content(self):
        reload_module(self.module)
        split_output = get_stdout().split('\n')
        self.assertEqual(len(split_output), 7, 'Output was expected to have {0} lines, your program\'s output is now in {1} lines.'.format(7, len(split_output)))
        correct = "Alsasua Baztan Estella Olite Pamplona Tafalla Tudela".split()
        for i in range(7):
            self.assertEqual(split_output[i], correct[i], "Line {0} in output is incorrect.".format(i + 1))

if __name__ == '__main__':
    unittest.main()

